@-moz-document regexp("https?://.*") {
/* Default Position: Bottom Right (for general & small pages) */
  body::after {
    content: "";
    position: fixed;
    bottom: 24px;
    right: 24px;
    width: 54px;
    height: 62px;
    z-index: 2147483647;
    pointer-events: none; /* Lets you click links underneath the cube */
    filter: drop-shadow(0 6px 10px rgba(0, 0, 0, 0.35));
    animation: rubiks-float 3s ease-in-out infinite;
    
    /* Isometric 3x3 Rubik's Cube SVG */
    background-repeat: no-repeat;
    background-size: contain;
    background-image: url("data:image/svg+xml,%3Csvg xmlns='http://w3.org' viewBox='0 0 120 138'%3E%3Cg stroke='%23111' stroke-width='3' stroke-linejoin='round'%3E%3C!-- Top Face (White) --%3E%3Cpolygon points='60,4 80,15.5 60,27 40,15.5' fill='%23ffffff'/%3E%3Cpolygon points='80,15.5 100,27 80,38.5 60,27' fill='%23ffffff'/%3E%3Cpolygon points='100,27 116,36.2 96,47.7 80,38.5' fill='%23ffffff'/%3E%3Cpolygon points='40,15.5 60,27 40,38.5 20,27' fill='%23ffffff'/%3E%3Cpolygon points='60,27 80,38.5 60,50 40,38.5' fill='%23ffffff'/%3E%3Cpolygon points='80,38.5 96,47.7 76,59.2 60,50' fill='%23ffffff'/%3E%3Cpolygon points='20,27 40,38.5 20,50 4,40.8' fill='%23ffffff'/%3E%3Cpolygon points='40,38.5 60,50 40,61.5 20,50' fill='%23ffffff'/%3E%3Cpolygon points='60,50 76,59.2 60,68.5 40,61.5' fill='%23ffffff'/%3E%3C!-- Left Face (Red/Orange mix) --%3E%3Cpolygon points='4,40.8 20,50 20,73 4,63.8' fill='%23e53935'/%3E%3Cpolygon points='20,50 40,61.5 40,84.5 20,73' fill='%23fb8c00'/%3E%3Cpolygon points='40,61.5 60,68.5 60,91.5 40,84.5' fill='%23e53935'/%3E%3Cpolygon points='4,63.8 20,73 20,96 4,86.8' fill='%23fdd835'/%3E%3Cpolygon points='20,73 40,84.5 40,107.5 20,96' fill='%23e53935'/%3E%3Cpolygon points='40,84.5 60,91.5 60,114.5 40,107.5' fill='%23ffffff'/%3E%3Cpolygon points='4,86.8 20,96 20,114.5 4,105.3' fill='%23e53935'/%3E%3Cpolygon points='20,96 40,107.5 40,126 20,114.5' fill='%2343a047'/%3E%3Cpolygon points='40,107.5 60,114.5 60,134 40,126' fill='%23e53935'/%3E%3C!-- Right Face (Blue/Green/Yellow mix) --%3E%3Cpolygon points='60,68.5 76,59.2 76,82.2 60,91.5' fill='%231e88e5'/%3E%3Cpolygon points='76,59.2 96,47.7 96,70.7 76,82.2' fill='%2343a047'/%3E%3Cpolygon points='96,47.7 116,36.2 116,59.2 96,70.7' fill='%231e88e5'/%3E%3Cpolygon points='60,91.5 76,82.2 76,105.2 60,114.5' fill='%23fb8c00'/%3E%3Cpolygon points='76,82.2 96,70.7 96,93.7 76,105.2' fill='%231e88e5'/%3E%3Cpolygon points='96,70.7 116,59.2 116,82.2 96,93.7' fill='%23fdd835'/%3E%3Cpolygon points='60,114.5 76,105.2 76,124.7 60,134' fill='%231e88e5'/%3E%3Cpolygon points='76,105.2 96,93.7 96,113.2 76,124.7' fill='%231e88e5'/%3E%3Cpolygon points='96,93.7 116,82.2 116,101.7 96,113.2' fill='%2343a047'/%3E%3C/g%3E%3C/svg%3E");
  }

  @keyframes rubiks-float {
    0%, 100% { transform: translateY(0px); }
    50% { transform: translateY(-6px); }
  }
}

@-moz-document domain("youtube.com") {
body::after {
    top: 10px;
    right: 220px;
    bottom: auto;
    left: auto;
    width: 38px;
    height: 44px;
  }
}

@-moz-document domain("google.com") {
body::after {
    top: 75px;
    right: 30px;
    bottom: auto;
    left: auto;
  }
}

@-moz-document domain("reddit.com") {
body::after {
    bottom: 24px;
    left: 24px;
    right: auto;
    top: auto;
  }
}

@-moz-document domain("x.com"), domain("twitter.com") {
body::after {
    top: 16px;
    right: 24px;
    bottom: auto;
    left: auto;
    width: 44px;
    height: 50px;
  }
}

@-moz-document domain("github.com") {
body::after {
    bottom: 24px;
    left: 24px;
    right: auto;
    top: auto;
  }
}

@-moz-document domain("wikipedia.org") {
body::after {
    top: 16px;
    left: 24px;
    right: auto;
    bottom: auto;
  }
}
